
import os  
import re  
import pandas as pd
import numpy as np
df_aggregated = {'values':[[[10, 3, 4], [1, 3, 20]], [[5, 4, 4]]]}
id2label_infer = {0:'PO', 1:'PI', 2:'OTHERS'}
df_aggregated = pd.DataFrame(df_aggregated)
df_aggregated["probs"]=df_aggregated["values"].apply(lambda x:np.mean(np.array(x), axis=0))
# print(df_aggregated["probs"])
df_aggregated["predicted_label"] = df_aggregated["probs"].apply(lambda x:id2label_infer[np.argmax(x)])
print(df_aggregated)
exit('OL')
exit()
import torch
import torch.nn as nn
import numpy as np

# Create a simple position embedding layer
x_topleft_embeddings = nn.Embedding(1000, 96)

# Let's look at some example positions:
positions = torch.tensor([0, 100, 500, 999])  # Different x positions
print(positions)
# Get the embeddings for these positions
embeddings = x_topleft_embeddings(positions)
print(embeddings[3])
print(len(embeddings[2]))
exit('OP')
# Convert to numpy for easier viewing
embedding_values = embeddings.detach().numpy()

print("Example embedding values for different x positions:")
print(f"Shape of embeddings: {embedding_values.shape}")  # Will be (4, 96)

# Show first 10 values for each position
for pos, emb in zip(positions, embedding_values):
    print(f"\nPosition {pos} embedding (first 10 dimensions):")
    print(np.round(emb[:10], 3))  # Round to 3 decimal places for readability

